    char* tab = strchr(line, '\t'); if (!tab) continue; *tab = 0;
    char* nl = strchr(tab+1, '\n'); if (nl) *nl = 0;
    size_t plen, slen;
    unsigned char* pat = unhex(line, &plen);
    unsigned char* str = unhex(tab+1, &slen);
    pid_t pid = fork();
    if (pid == 0) {
      regex_t rx; regmatch_t m[1];
      if (regcomp(&rx, (const char*)pat, REG_EXTENDED|REG_NEWLINE)) _exit(3);
      memset(m, 0xAA, sizeof m);
      int rc = regexec(&rx, (const char*)str, 1, m, 0);
      if (rc == 0) _exit(42);
      _exit(0);
    }
    int st; waitpid(pid, &st, 0);
    free(pat); free(str);
    if (WIFEXITED(st)) {
      if (WEXITSTATUS(st)==42) matched++;
      else if (WEXITSTATUS(st)==0) compok++;
    }
    if (idx % 50000 == 0) { fprintf(stderr, "progress %ld jobs=%ld comp=%ld match=%ld\n", idx, jobs, compok, matched); }
  }
  fprintf(stderr, "TOTAL jobs=%ld comp=%ld match=%ld\n", jobs, compok, matched);
  return 0;
  (void)unhex;
}
